/// Administrators only (`content.manage`). Accepts a multipart upload of v1-shaped content and upserts rows under the singleton `custom` source:  - `testcases_json` — v1 `custom/testcases.json` (array or `{testcases:[…]}`) - `testcases_yaml` — one YAML file or a zip of `*.yaml` testcase files   (the layout the v1 seeder globbed as `custom/testcases/_*.yaml`) - `knowledgebase_yaml` — one YAML file or a zip of KB notes - `auto` — sniff JSON testcases, KB yaml, testcase yaml, custom export,   or a zip of the above  Small uploads run synchronously and answer `200` with counts/warnings. Uploads over the sync threshold (1 MiB) enqueue a `v1_import` job and answer `202` (same global job slot as content sync). `dryRun=true` always runs synchronously and never writes.  Partial file failures are reported per path and do not abort the rest unless `failFast=true`. Re-import is idempotent: external ids are derived deterministically from v1 ids/names (see `docs/content-v1-import.md`). 
pub async fn import_custom_content(configuration: &configuration::Configuration, file: std::path::PathBuf, x_csrf_token: Option<&str>, dry_run: Option<bool>, fail_fast: Option<bool>, format: Option<&str>) -> Result<models::ContentImportReport, Error<ImportCustomContentError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_form_file = file;
    let p_header_x_csrf_token = x_csrf_token;
    let p_query_dry_run = dry_run;
    let p_query_fail_fast = fail_fast;
    let p_form_format = format;

    let uri_str = format!("{}/content/custom/import", configuration.base_path);
    let mut req_builder = configuration.client.request(reqwest::Method::POST, &uri_str);

    if let Some(ref param_value) = p_query_dry_run {
        req_builder = req_builder.query(&[("dryRun", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_fail_fast {
        req_builder = req_builder.query(&[("failFast", &param_value.to_string())]);
    }
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(param_value) = p_header_x_csrf_token {
        req_builder = req_builder.header("X-CSRF-Token", param_value.to_string());
    }
    if let Some(ref token) = configuration.bearer_access_token {
        req_builder = req_builder.bearer_auth(token.to_owned());
    };
    let mut multipart_form = reqwest::multipart::Form::new();
    let file = TokioFile::open(&p_form_file).await?;
    let stream = FramedRead::new(file, BytesCodec::new());
    let file_name = p_form_file.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    let file_part = reqwest::multipart::Part::stream(reqwest::Body::wrap_stream(stream)).file_name(file_name);
    multipart_form = multipart_form.part("file", file_part);
    if let Some(param_value) = p_form_format {
        multipart_form = multipart_form.text("format", param_value.to_string());
    }
    req_builder = req_builder.multipart(multipart_form);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::ContentImportReport`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::ContentImportReport`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<ImportCustomContentError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

