/// Administrators only (`content.sync`). Accepts a multipart release archive (zip / tar.gz) whose bytes match what the adapter's HTTPS fetch would have produced. Creates a `bundle_import` job and runs Parse → Normalize → Apply with no network Fetch. The upload is spooled under the content data directory; archives larger than `BLACKLIGHT_CONTENT_MAX_BYTES` are refused before a job is enqueued, with the limit named in the problem detail.  Takes the same global job slot as online sync (`409` when another job is active). Progress streams over `GET /events` exactly like sync.  See `docs/content-bundles.md` for per-kind archive layout and how to obtain a bundle on a connected machine. 
pub async fn upload_content_source_bundle(configuration: &configuration::Configuration, source_id: &str, file: std::path::PathBuf, x_csrf_token: Option<&str>, version: Option<&str>) -> Result<models::ContentSyncJob, Error<UploadContentSourceBundleError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_path_source_id = source_id;
    let p_form_file = file;
    let p_header_x_csrf_token = x_csrf_token;
    let p_form_version = version;

    let uri_str = format!("{}/content/sources/{sourceId}/bundle", configuration.base_path, sourceId=crate::apis::urlencode(p_path_source_id));
    let mut req_builder = configuration.client.request(reqwest::Method::POST, &uri_str);

    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(param_value) = p_header_x_csrf_token {
        req_builder = req_builder.header("X-CSRF-Token", param_value.to_string());
    }
    if let Some(ref token) = configuration.bearer_access_token {
        req_builder = req_builder.bearer_auth(token.to_owned());
    };
    let mut multipart_form = reqwest::multipart::Form::new();
    let file = TokioFile::open(&p_form_file).await?;
    let stream = FramedRead::new(file, BytesCodec::new());
    let file_name = p_form_file.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    let file_part = reqwest::multipart::Part::stream(reqwest::Body::wrap_stream(stream)).file_name(file_name);
    multipart_form = multipart_form.part("file", file_part);
    if let Some(param_value) = p_form_version {
        multipart_form = multipart_form.text("version", param_value.to_string());
    }
    req_builder = req_builder.multipart(multipart_form);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::ContentSyncJob`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::ContentSyncJob`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<UploadContentSourceBundleError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

